\begin{theorem}
[Albanese universal property of \(\Pic^0_{C/k}\) (Milne III Prop 6.1)]
  \label{thm:albanese_universal_property_northstar}

  \lean{AlgebraicGeometry.Scheme.Pic.albaneseUP}
